#include "opaque_km_arithmetic.hpp"
MCycle ob_cycle(const EBPoly& f,const std::vector<BasePoint>& points,const std::vector<int>& multiplicities){
    require(points.size()==multiplicities.size(),"boundary cycle support widths");MCycle out;out.dimension=3;
    for(int l=0;l<=8;++l){std::vector<Z> z;bool good=true;int degree=0;for(size_t i=0;i<points.size();++i){auto& p=points[i];require(f.eval(Z(p.x),p.y)==Z(0),"boundary input point on quartic");degree+=multiplicities[i];z.push_back(Z(p.x)+Z(l)*p.y);if((f.partial(1)-f.partial(0).scale(Z(l))).eval(Z(p.x),p.y)==Z(0))good=false;}require(degree==3,"boundary effective degree3");for(size_t i=0;i<z.size();++i)for(size_t j=0;j<i;++j)if(z[i]==z[j])good=false;if(!good){out.rejected.push_back(l);continue;}CFPoly u{Z(1)},y,x{Z(0),Z(1)};for(size_t i=0;i<z.size();++i){for(int j=0;j<multiplicities[i];++j)u=u*CFPoly{-z[i],Z(1)};CFPoly lagrange{points[i].y};for(size_t j=0;j<z.size();++j)if(i!=j)lagrange=(lagrange*CFPoly{-z[j],Z(1)}).scale((z[i]-z[j]).inv());y=y+lagrange;}auto transverse=f.partial(1)-f.partial(0).scale(Z(l));for(int k=1;k<3;k*=2){auto xx=(x-y.scale(Z(l)))%u;auto error=cm_curve(f,u,xx,y),dy=cm_curve(transverse,u,xx,y);y=(y-error*cm_inverse(dy,u))%u;}out.u=u;out.x=(x-y.scale(Z(l)))%u;out.y=y;out.coordinate=l;require(cm_curve(f,u,out.x,out.y).degree()<0,"boundary full repeated cycle incidence");return out;}
    throw std::runtime_error("boundary rational cycle separating schedule");
}
void ob_support(const MCycle& cycle,const std::vector<BasePoint>& points,const std::vector<int>& multiplicities){CFPoly u{Z(1)};for(size_t i=0;i<points.size();++i){Z z=Z(points[i].x)+Z(cycle.coordinate)*points[i].y;for(int j=0;j<multiplicities[i];++j)u=u*CFPoly{-z,Z(1)};require(cycle.x.eval(z)==Z(points[i].x)&&cycle.y.eval(z)==points[i].y,"boundary decoded support coordinates");}require(cycle.u==u,"boundary decoded exact multiplicities");}
